"import os
import math

def write_file(path, content):
    """Utility to write file content creating directories if needed."""
    dirname = os.path.dirname(path)
    if dirname:
        os.makedirs(dirname, exist_ok=True)
    with open(path, 'w') as f:
        f.write(content)

# --- Directory Structure ---
# Directories are created implicitly by write_file, but let's ensure basics
os.makedirs("0", exist_ok=True)
os.makedirs("constant", exist_ok=True)
os.makedirs("constant/polyMesh", exist_ok=True)
os.makedirs("system", exist_ok=True)

